71: 	@RequestMapping(method = RequestMethod.POST)
72: 	@ResponseStatus(HttpStatus.OK)
73: 	public void updateCurrentConfiguration(@RequestBody VisitConfiguration newConfiguration) throws SchedulerException {
74: 		Context.requirePrivilege(PrivilegeConstants.CONFIGURE_VISITS);
75: 		AdministrationService administrationService = Context.getAdministrationService();
76: 		EncounterService encounterService = Context.getEncounterService();
77: 		VisitService visitService = Context.getVisitService();
78: 		SchedulerService schedulerService = Context.getSchedulerService();
79: 
80: 		// validate
81: 		if (newConfiguration.getEnableVisits() && StringUtils.isEmpty(newConfiguration.getEncounterVisitsAssignmentHandler())) {
82: 			throw new IllegalRequestException("Encounter Visit assignment handler cannot be empty");
83: 		}
84: 
85: 		administrationService
86: 				.setGlobalProperty(OpenmrsConstants.GLOBAL_PROPERTY_ENABLE_VISITS, Boolean.toString(newConfiguration.getEnableVisits()));
87: 
88: 		if (newConfiguration.getEnableVisits()) {
89: 			String newEncounterVisitsAssignmentHandler = newConfiguration.getEncounterVisitsAssignmentHandler();
90: 			if (isEncounterVisitsAssignmentHandlerValid(newEncounterVisitsAssignmentHandler, encounterService)) {
91: 				administrationService
92: 						.setGlobalProperty(OpenmrsConstants.GP_VISIT_ASSIGNMENT_HANDLER, newEncounterVisitsAssignmentHandler);
93: 			} else {
94: 				throw new IllegalPropertyException(
95: 						"Provided encounterVisitsAssignmentHandler class " + newEncounterVisitsAssignmentHandler + " does not exist.");
96: 			}
97: 		}
98: 		updateGetAutoCloseVisitsTaskStartedValue(schedulerService, newConfiguration.getStartAutoCloseVisitsTask());
99: 		updateVisitTypesToAutoCloseValue(administrationService, visitService, newConfiguration.getVisitTypesToAutoClose());
100: 	}
