102: 	private Boolean getEnableVisitsValue(AdministrationService administrationService) {
103: 		String enableVisits = administrationService
104: 				.getGlobalProperty(OpenmrsConstants.GLOBAL_PROPERTY_ENABLE_VISITS, "true");
105: 		return Boolean.parseBoolean(enableVisits);
106: 	}
107: 
108: 	private Boolean getAutoCloseVisitsTaskStartedValue(SchedulerService schedulerService) {
109: 		try {
110: 			TaskDefinition autoCloseVisitsTaskStarted = schedulerService
111: 					.getTaskByName(OpenmrsConstants.AUTO_CLOSE_VISITS_TASK_NAME);
112: 			if (autoCloseVisitsTaskStarted != null) {
113: 				return autoCloseVisitsTaskStarted.getStarted();
114: 			}
115: 		}
116: 		catch (ObjectRetrievalFailureException e) {
117: 			// task not configured — treat as not started
118: 		}
119: 		return false;
120: 	}
121: 
122: 	private void updateGetAutoCloseVisitsTaskStartedValue(SchedulerService schedulerService,
123: 			Boolean autoCloseVisitsTaskStarted) throws SchedulerException {
124: 		TaskDefinition closeVisitsTask;
125: 		try {
126: 			closeVisitsTask = schedulerService.getTaskByName(OpenmrsConstants.AUTO_CLOSE_VISITS_TASK_NAME);
127: 		}
128: 		catch (ObjectRetrievalFailureException e) {
129: 			return;
130: 		}
131: 		if (closeVisitsTask != null) {
132: 			if (autoCloseVisitsTaskStarted && !closeVisitsTask.getStarted()) {
133: 				schedulerService.scheduleTask(closeVisitsTask);
134: 			} else if (!autoCloseVisitsTaskStarted && closeVisitsTask.getStarted()) {
135: 				schedulerService.shutdownTask(closeVisitsTask);
136: 			}
137: 		}
138: 	}
139: 
140: 	private List<VisitType> getVisitTypesToAutoCloseValue(AdministrationService administrationService,
141: 			VisitService visitService) {
142: 		String gpValue = administrationService.getGlobalProperty(OpenmrsConstants.GP_VISIT_TYPES_TO_AUTO_CLOSE);
143: 		if (StringUtils.isNotBlank(gpValue)) {
144: 			List<VisitType> visitTypes = new ArrayList<>();
145: 			String[] visitTypeNames = StringUtils.split(gpValue.trim(), ",");
146: 			for (int i = 0; i < visitTypeNames.length; i++) {
147: 				String currName = visitTypeNames[i];
148: 				visitTypeNames[i] = currName.trim().toLowerCase();
149: 			}
150: 
151: 			List<VisitType> allVisitTypes = visitService.getAllVisitTypes();
152: 			for (VisitType visitType : allVisitTypes) {
153: 				if (ArrayUtils.contains(visitTypeNames, visitType.getName().toLowerCase())) {
154: 					visitTypes.add(visitType);
155: 				}
156: 			}
157: 			return visitTypes;
158: 		}
159: 		return Collections.emptyList();
160: 	}
